/**
 * T1 tier — the API origin verification secret of a CloudFront deployment (issue #714).
 *
 * CloudFront adds `x-vams-origin-verify` to every request it forwards to the REST API, carrying the
 * `current` value of a per-deployment AWS Secrets Manager secret. The regional web ACL's rate rules
 * and the REST authorizer's client-address resolution read it. Pinned here:
 *
 *   - the secret has a stack of its own, generated by Secrets Manager (no value in any template), and
 *     every reader references it through a `{{resolve:secretsmanager:...}}` dynamic reference or by ARN;
 *   - both API origins of the distribution carry the header; the web bucket origin does not;
 *   - the rotation schedule rotates every 45 days (a value is accepted for at most two intervals,
 *     about 90 days), does not rotate on deploy, and invokes a function
 *     whose permission names this account as its source;
 *   - the REST authorizer reads the secret by ARN;
 *   - with a customer managed key the secret is encrypted with it and both readers can decrypt, for
 *     this secret only (`kms:EncryptionContext:SecretARN`);
 *   - deployments without CloudFront (the GovCloud and EU Sovereign templates, both ALB-fronted)
 *     emit none of it.
 *
 * The regional web ACL scope-down is asserted on the construct (`test/waf/wafRateLimit.test.ts`): the
 * T1 harness builds no WAF stack.
 *
 * Durable (root CLAUDE.md Rule 13).
 */

import { Template } from "aws-cdk-lib/assertions";
import * as Config from "../../config/config";
import commercialTemplate from "../../config/config.template.commercial.json";
import { ApiOriginVerifyStack } from "../../lib/apiOriginVerify-stack";
import { newTestApp } from "../support/testApp";
import {
    expectAbsent,
    RESTRICTED_TEMPLATES,
    Resource,
    SynthResult,
    synthTemplate,
} from "../support/templateSynth";

jest.setTimeout(900_000);

const HEADER = "x-vams-origin-verify";
const ROTATION_HANDLER = "handlers.auth.apiOriginVerifyRotation.lambda_handler";
const AUTHORIZER_HANDLER = "handlers.auth.apiGatewayAuthorizerRest.lambda_handler";
// The secret ARN reaches the core stack's nested stacks as an import of the origin verification
// stack's export (flattened by SynthResult.flatten).
const SECRET_ARN_IMPORT =
    "[^:{}]*origin-verify[^:{}]*:ExportsOutputRefApiOriginVerifySecret[^:{}]*";
const SECRET_ARN = new RegExp(`^${SECRET_ARN_IMPORT}$`);
const DYNAMIC_CURRENT = new RegExp(
    `^\\{\\{resolve:secretsmanager:${SECRET_ARN_IMPORT}:SecretString:current::\\}\\}$`
);

/** The value is an Fn::ImportValue (directly or inside Fn::Join), never a literal ARN or value. */
const isImported = (value: any) => JSON.stringify(value).includes("Fn::ImportValue");

const originVerifyStackKeys = (s: SynthResult) =>
    Object.keys(s.templates).filter((k) => /origin-verify/.test(k));

function secrets(s: SynthResult): Resource[] {
    return s.ofType("AWS::SecretsManager::Secret").filter((r) => /origin-verify/.test(r.stack));
}

function lambdaByHandler(s: SynthResult, handler: string): Resource {
    const found = s.ofType("AWS::Lambda::Function").filter((f) => f.properties.Handler === handler);
    expect(found).toHaveLength(1);
    return found[0];
}

/** Every statement of every IAM policy attached to a function's own role. */
function roleStatements(s: SynthResult, fn: Resource): any[] {
    const roleLogicalId = fn.properties.Role?.["Fn::GetAtt"]?.[0];
    expect(roleLogicalId).toBeDefined();
    return s
        .ofType("AWS::IAM::Policy")
        .filter(
            (p) =>
                p.stack === fn.stack &&
                (p.properties.Roles ?? []).some((r: any) => r.Ref === roleLogicalId)
        )
        .flatMap((p) => p.properties.PolicyDocument.Statement);
}

const actionsOf = (st: any): string[] => ([] as string[]).concat(st.Action ?? []);

function statementWith(statements: any[], action: string): any {
    const found = statements.filter((st) => actionsOf(st).includes(action));
    expect(found).toHaveLength(1);
    return found[0];
}

/** Origins of the web distribution, keyed by whether they carry the origin verification header. */
function distributionOrigins(s: SynthResult): any[] {
    const distributions = s
        .ofType("AWS::CloudFront::Distribution")
        .filter((r) => /StaticWeb/.test(r.stack));
    expect(distributions).toHaveLength(1);
    return distributions[0].properties.DistributionConfig.Origins;
}

const originVerifyHeaders = (origin: any): any[] =>
    (origin.OriginCustomHeaders ?? []).filter((h: any) => h.HeaderName === HEADER);

describe("API origin verification (commercial, CloudFront)", () => {
    const s = () => synthTemplate("commercial");

    test("the secret has a stack of its own with one generated secret", () => {
        expect(originVerifyStackKeys(s())).toHaveLength(1);
        const found = secrets(s());
        expect(found).toHaveLength(1);
        const props = found[0].properties;
        expect(props.GenerateSecretString).toEqual({
            SecretStringTemplate: "{}",
            GenerateStringKey: Config.API_ORIGIN_VERIFY_CURRENT_KEY,
            ExcludePunctuation: true,
            PasswordLength: 64,
        });
        // Generated by Secrets Manager: no value in the template, and auto-named.
        expect(props.SecretString).toBeUndefined();
        expect(props.Name).toBeUndefined();
        expect(found[0].raw.DeletionPolicy).toBe("Delete");
        // CMK off in the shipped commercial template: the AWS managed key.
        expect(props.KmsKeyId).toBeUndefined();
    });

    test("both API origins carry the header as a dynamic reference; the bucket origin does not", () => {
        const origins = distributionOrigins(s());
        const api = origins.filter((o) => o.CustomOriginConfig);
        expect(api).toHaveLength(2);
        api.forEach((origin) => {
            const headers = originVerifyHeaders(origin);
            expect(headers).toHaveLength(1);
            expect(SynthResult.flatten(headers[0].HeaderValue)).toMatch(DYNAMIC_CURRENT);
            expect(isImported(headers[0].HeaderValue)).toBe(true);
        });
        origins
            .filter((o) => !o.CustomOriginConfig)
            .forEach((origin) => expect(originVerifyHeaders(origin)).toEqual([]));
    });

    test("the rotation schedule rotates every 45 days and not on deploy", () => {
        const schedules = s().ofType("AWS::SecretsManager::RotationSchedule");
        expect(schedules).toHaveLength(1);
        const props = schedules[0].properties;
        expect(schedules[0].stack).toMatch(/StaticWeb/);
        expect(props.RotationRules).toEqual({ ScheduleExpression: "rate(45 days)" });
        // A value stays accepted as `previous` for one more interval after it is rotated out, so
        // its total lifetime is two intervals; that must stay within 90 days.
        expect(Config.API_ORIGIN_VERIFY_ROTATION_DAYS).toBe(45);
        expect(2 * Config.API_ORIGIN_VERIFY_ROTATION_DAYS).toBeLessThanOrEqual(90);
        expect(props.RotateImmediatelyOnUpdate).toBe(false);
        const rotation = lambdaByHandler(s(), ROTATION_HANDLER);
        expect(props.RotationLambdaARN).toEqual({ "Fn::GetAtt": [rotation.logicalId, "Arn"] });
    });

    test("Secrets Manager may invoke the rotation function for this account only", () => {
        const rotation = lambdaByHandler(s(), ROTATION_HANDLER);
        const permissions = s()
            .ofType("AWS::Lambda::Permission")
            .filter(
                (p) =>
                    p.stack === rotation.stack &&
                    JSON.stringify(p.properties.FunctionName).includes(rotation.logicalId)
            );
        expect(permissions).toHaveLength(1);
        expect(permissions[0].properties.Principal).toBe("secretsmanager.amazonaws.com");
        expect(permissions[0].properties.SourceAccount).toBeDefined();
    });

    test("the rotation function targets the distribution, runs outside the VPC and is granted no more", () => {
        const rotation = lambdaByHandler(s(), ROTATION_HANDLER);
        expect(rotation.properties.VpcConfig).toBeUndefined();
        const env = rotation.properties.Environment.Variables;
        expect(env.ORIGIN_VERIFY_DISTRIBUTION_ID).toEqual({ Ref: expect.any(String) });
        // The T1 harness builds no WAF stack, so there is no regional web ACL to update.
        expect(env.ORIGIN_VERIFY_WEB_ACL_ARN).toBeUndefined();

        const statements = roleStatements(s(), rotation);
        const secretStatement = statementWith(statements, "secretsmanager:PutSecretValue");
        expect(actionsOf(secretStatement).sort()).toEqual(
            [
                "secretsmanager:DescribeSecret",
                "secretsmanager:GetSecretValue",
                "secretsmanager:PutSecretValue",
                "secretsmanager:UpdateSecretVersionStage",
            ].sort()
        );
        expect(SynthResult.flatten(secretStatement.Resource)).toMatch(SECRET_ARN);
        expect(isImported(secretStatement.Resource)).toBe(true);
        expect(statementWith(statements, "secretsmanager:GetRandomPassword").Resource).toBe("*");
        const cloudfront = statementWith(statements, "cloudfront:UpdateDistribution");
        expect(SynthResult.flatten(cloudfront.Resource)).toMatch(/:cloudfront::.*:distribution\//);
        expect(statements.flatMap(actionsOf).filter((a) => a.startsWith("wafv2:"))).toEqual([]);
    });

    test("the REST authorizer reads the secret by ARN", () => {
        const authorizer = lambdaByHandler(s(), AUTHORIZER_HANDLER);
        const env = authorizer.properties.Environment.Variables;
        expect(env.API_FRONTED).toBe("cloudfront");
        expect(SynthResult.flatten(env.ORIGIN_VERIFY_SECRET_ARN)).toMatch(SECRET_ARN);
        expect(isImported(env.ORIGIN_VERIFY_SECRET_ARN)).toBe(true);
        const read = statementWith(
            roleStatements(s(), authorizer),
            "secretsmanager:GetSecretValue"
        );
        expect(actionsOf(read)).toEqual(["secretsmanager:GetSecretValue"]);
        expect(read.Resource).toEqual(env.ORIGIN_VERIFY_SECRET_ARN);
    });

    test("every reference to the secret value is a dynamic reference", () => {
        const references = s().grep("{{resolve:secretsmanager:");
        // The two origin headers. Nothing else in the T1 assembly resolves the secret.
        expect(references.map((r) => r.type)).toEqual(["AWS::CloudFront::Distribution"]);
    });
});

describe("API origin verification with a VAMS-generated customer managed key", () => {
    const s = () =>
        synthTemplate("commercial", {
            mutateKey: "origin-verify-cmk",
            mutate: (c: any) => {
                c.app.useKmsCmkEncryption = { enabled: true, optionalExternalCmkArn: "" };
            },
        });

    test("the secret's stack holds its own retained key, because the shared key deploys later", () => {
        const stack = originVerifyStackKeys(s())[0];
        const keys = s()
            .ofType("AWS::KMS::Key")
            .filter((k) => k.stack === stack);
        expect(keys).toHaveLength(1);
        expect(keys[0].properties.EnableKeyRotation).toBe(true);
        expect(keys[0].raw.DeletionPolicy).toBe("Retain");
        expect(secrets(s())[0].properties.KmsKeyId).toEqual({
            "Fn::GetAtt": [keys[0].logicalId, "Arn"],
        });
    });

    test("the authorizer and the rotation function can use the key for this secret only", () => {
        const authorizer = lambdaByHandler(s(), AUTHORIZER_HANDLER);
        const decrypt = roleStatements(s(), authorizer).filter(
            (st) => actionsOf(st).length === 1 && actionsOf(st)[0] === "kms:Decrypt"
        );
        expect(decrypt).toHaveLength(1);

        const rotation = lambdaByHandler(s(), ROTATION_HANDLER);
        const kms = roleStatements(s(), rotation).filter((st) =>
            actionsOf(st).includes("kms:GenerateDataKey")
        );
        expect(kms).toHaveLength(1);
        expect(actionsOf(kms[0]).sort()).toEqual(
            ["kms:Decrypt", "kms:Encrypt", "kms:GenerateDataKey"].sort()
        );
        expect(kms[0].Resource).toEqual(decrypt[0].Resource);

        // Both grants are limited to the secret through the encryption context Secrets Manager
        // passes to AWS KMS, and to the secret's own ARN (an import of the origin verification
        // stack's export), with no other condition.
        for (const statement of [decrypt[0], kms[0]]) {
            expect(Object.keys(statement.Condition ?? {})).toEqual(["StringEquals"]);
            const context = statement.Condition.StringEquals;
            expect(Object.keys(context)).toEqual(["kms:EncryptionContext:SecretARN"]);
            expect(SynthResult.flatten(context["kms:EncryptionContext:SecretARN"])).toMatch(
                SECRET_ARN
            );
            expect(isImported(context["kms:EncryptionContext:SecretARN"])).toBe(true);
        }
        const authorizerSecretArn =
            authorizer.properties.Environment.Variables.ORIGIN_VERIFY_SECRET_ARN;
        expect(decrypt[0].Condition.StringEquals["kms:EncryptionContext:SecretARN"]).toEqual(
            authorizerSecretArn
        );
    });
});

describe("ApiOriginVerifyStack key selection", () => {
    function stackTemplate(useKmsCmkEncryption: any): Template {
        const config = JSON.parse(JSON.stringify(commercialTemplate)) as Config.Config;
        config.app.useKmsCmkEncryption = useKmsCmkEncryption;
        const app = newTestApp();
        const stack = new ApiOriginVerifyStack(app, "OriginVerifyTest", {
            env: { account: "123456789012", region: "us-east-1" },
            stackName: "vams-origin-verify-test",
            description: "test",
            config,
        });
        return Template.fromStack(stack);
    }

    test("an external customer managed key is used as is", () => {
        const externalKey =
            "arn:aws:kms:us-east-1:123456789012:key/11111111-2222-3333-4444-555555555555";
        const template = stackTemplate({ enabled: true, optionalExternalCmkArn: externalKey });
        template.resourceCountIs("AWS::KMS::Key", 0);
        template.hasResourceProperties("AWS::SecretsManager::Secret", { KmsKeyId: externalKey });
    });

    test("CMK encryption off uses the AWS managed key", () => {
        const template = stackTemplate({ enabled: false, optionalExternalCmkArn: "" });
        template.resourceCountIs("AWS::KMS::Key", 0);
        template.resourceCountIs("AWS::SecretsManager::Secret", 1);
        const secret = Object.values(template.findResources("AWS::SecretsManager::Secret"))[0];
        expect((secret as any).Properties.KmsKeyId).toBeUndefined();
    });
});

describe.each(RESTRICTED_TEMPLATES)("%s (ALB, no CloudFront) emits nothing of it", (name) => {
    const s = () => synthTemplate(name);
    const commercial = () => synthTemplate("commercial");

    test("no origin verification stack", () => {
        expectAbsent("an origin verification stack", originVerifyStackKeys(s()), {
            description: "commercial emits the stack",
            count: originVerifyStackKeys(commercial()).length,
        });
    });

    test("no resource names the header, the secret or the rotation function", () => {
        const needle = new RegExp(`${HEADER}|ORIGIN_VERIFY_|apiOriginVerifyRotation`);
        expectAbsent("a resource mentioning origin verification", s().grep(needle), {
            description: "commercial resources mention it",
            count: commercial().grep(needle).length,
        });
    });

    test("no rotation schedule", () => {
        expectAbsent(
            "a Secrets Manager rotation schedule",
            s().ofType("AWS::SecretsManager::RotationSchedule"),
            {
                description: "commercial emits one",
                count: commercial().countOfType("AWS::SecretsManager::RotationSchedule"),
            }
        );
    });

    test("the authorizer is not fronted by CloudFront and reads no secret", () => {
        const authorizer = lambdaByHandler(s(), AUTHORIZER_HANDLER);
        expect(authorizer.properties.Environment.Variables.API_FRONTED).toBe("alb");
        expect(
            authorizer.properties.Environment.Variables.ORIGIN_VERIFY_SECRET_ARN
        ).toBeUndefined();
    });
});
